function controls_data (value){
				let currentWrapper = "mf-response-props-id-290";
				let currentEl = document.getElementById(currentWrapper);
				
				return currentEl ? currentEl.dataset[value] : false
			}


			let is_edit_mode = '' ? true : false;
			let message_position = controls_data('messageposition') || 'top';

			
			let message_successIcon = controls_data('successicon') || '';
			let message_errorIcon = controls_data('erroricon') || '';
			let message_editSwitch = controls_data('editswitchopen') === 'yes' ? true : false;
			let message_proClass = controls_data('editswitchopen') === 'yes' ? 'mf_pro_activated' : '';
			
			let is_dummy_markup = is_edit_mode && message_editSwitch ? true : false;

			
			return html`
				<form
					className="metform-form-content"
					ref=${parent.formContainerRef}
					onSubmit=${ validation.handleSubmit( parent.handleFormSubmit ) }
				
					>
			
			
					${is_dummy_markup ? message_position === 'top' ?  props.ResponseDummyMarkup(message_successIcon, message_proClass) : '' : ''}
					${is_dummy_markup ? ' ' :  message_position === 'top' ? props.SubmitResponseMarkup`${parent}${state}${message_successIcon}${message_errorIcon}${message_proClass}` : ''}

					<!--------------------------------------------------------
					*** IMPORTANT / DANGEROUS ***
					${html``} must be used as in immediate child of "metform-form-main-wrapper"
					class otherwise multistep form will not run at all
					---------------------------------------------------------->

					<div className="metform-form-main-wrapper" key=${'hide-form-after-submit'} ref=${parent.formRef}>
					${html`
								<div data-elementor-type="wp-post" key="2" data-elementor-id="290" className="elementor elementor-290">
				<div className="elementor-element elementor-element-f0c5e93 e-con-full e-flex e-con e-parent" data-id="f0c5e93" data-element_type="container" data-e-type="container" data-settings="{&quot;tc_container_hover_selector&quot;:&quot;container&quot;,&quot;tc_container_background_parallax&quot;:&quot;no&quot;,&quot;tcg_advanced_hover&quot;:&quot;no&quot;,&quot;tc_dark_mode_responsive_hide_in_dark&quot;:&quot;no&quot;,&quot;tc_dark_mode_responsive_hide_in_light&quot;:&quot;no&quot;}">
				<div className="elementor-element elementor-element-15b0a05 elementor-widget elementor-widget-mf-email" data-id="15b0a05" data-element_type="widget" data-e-type="widget" data-settings="{&quot;mf_input_name&quot;:&quot;mf-email&quot;,&quot;tc_dark_mode_responsive_hide_in_dark&quot;:&quot;no&quot;,&quot;tc_dark_mode_responsive_hide_in_light&quot;:&quot;no&quot;}" data-widget_type="mf-email.default">
				<div className="elementor-widget-container">
					
		<div className="mf-input-wrapper">
							<label className="mf-input-label" htmlFor="mf-input-email-15b0a05">
					${ parent.decodeEntities(`Email Address`) } 					<span className="mf-input-required-indicator"></span>
				</label>
			
			<input 
				type="email" 
				 
				defaultValue="" 
				className="mf-input mf-conditional-input" 
				id="mf-input-email-15b0a05" 
				name="mf-email" 
				placeholder="${ parent.decodeEntities(`Enter your email address`) } " 
				 
				onBlur=${parent.handleChange} onFocus=${parent.handleChange} aria-invalid=${validation.errors['mf-email'] ? 'true' : 'false' } 
				ref=${el=> parent.activateValidation({"message":"This field is required.","emailMessage":"Please enter a valid Email address","minLength":1,"maxLength":"","type":"none","required":false,"expression":"null"}, el)}
							/>

						<${validation.ErrorMessage} 
				errors=${validation.errors} 
				name="mf-email" 
				as=${html`<span className="mf-error-message"></span>`}
			/>
			
					</div>

				</div>
				</div>
				<div className="elementor-element elementor-element-0fb341d elementor-absolute mf-btn--center elementor-widget elementor-widget-mf-button" data-id="0fb341d" data-element_type="widget" data-e-type="widget" data-settings="{&quot;_position&quot;:&quot;absolute&quot;,&quot;tc_dark_mode_responsive_hide_in_dark&quot;:&quot;no&quot;,&quot;tc_dark_mode_responsive_hide_in_light&quot;:&quot;no&quot;}" data-widget_type="mf-button.default">
				<div className="elementor-widget-container">
							<div className="mf-btn-wraper mf-conditional-input" data-mf-form-conditional-logic-requirement="">
							<button type="submit" className="metform-btn metform-submit-btn " id="">
					<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24"><path d="M2.69531 4.00781L3.02344 5.41406L4.47656 12L3.02344 18.5859L2.69531 19.9922L4.03125 19.4531L20.5312 12.7031L22.2422 12L20.5312 11.2969L4.03125 4.54688L2.69531 4.00781ZM4.78125 6.49219L16.4297 11.25H5.83594L4.78125 6.49219ZM5.83594 12.75H16.4297L4.78125 17.5078L5.83594 12.75Z"></path></svg>					<span>${ parent.decodeEntities(``) } </span>
				</button>
			        </div>
        				</div>
				</div>
				</div>
				</div>
							`}
					</div>

					${is_dummy_markup ? message_position === 'bottom' ? props.ResponseDummyMarkup(message_successIcon, message_proClass) : '' : ''}
					${is_dummy_markup ? ' ' : message_position === 'bottom' ? props.SubmitResponseMarkup`${parent}${state}${message_successIcon}${message_errorIcon}${message_proClass}` : ''}
				
				</form>
			`

